#include <Arduino.h>
#include <stdint.h>

static volatile uint32_t *reg32(uint32_t address) {
  return reinterpret_cast<volatile uint32_t *>(address);
}

void setup() {
  Serial.begin(115200);
  *reg32(0x40014084) = 4;         // GPIO16_CTRL.FUNCSEL = PWM
  *reg32(0x40050004) = 125u << 4; // PWM0 DIV = 125.0
  *reg32(0x40050010) = 19999;    // PWM0 TOP
  *reg32(0x4005000C) = 1500;     // PWM0 CC_A
  *reg32(0x40050000) = 1;        // PWM0 CSR.EN
  Serial.println("PICO_PWM_SERVO_GP16_OK");
}

void loop() {}
